sysauto_script.script:
(function executeRule() {
    var today = new GlideDateTime();
    var gr = new GlideRecord('x_vuram_financia_0_fcc_kyc_cases'); 
    gr.query();

    while (gr.next()) {
        var risk = gr.getValue('risk_level'); 
        var expiryDate = gr.getValue('kyc_expiry'); 
        if (!expiryDate || !risk) continue;

        var nextReviewDate = new GlideDateTime(expiryDate);

        // Add duration based on risk level
        if (risk === 'high') {
            nextReviewDate.addDaysUTC(365);
        } else if (risk === 'medium') {
            nextReviewDate.addDaysUTC(1095);
        } else if (risk === 'low') {
            nextReviewDate.addDaysUTC(1825);
        } else {
            continue;
        }

        // Subtract 60 days for early notification
        var notifyDate = new GlideDateTime(nextReviewDate);
        notifyDate.addDaysUTC(-60);

        // Flag if today >= notifyDate and not under review
        if (today.compareTo(notifyDate) >= 0 && gr.getValue('case_status') !== 'Under Review') {
            gr.setValue('kyc_due_soon', true);
            gr.update();

            // Trigger email and UI (bell icon) notifications
            gs.eventQueue('kyc.review.due.soon.email', gr, gr.assigned_to, gs.getUserID());
            gs.eventQueue('kyc.review.due.soon.ui', gr, gr.assigned_to, gs.getUserID());
        } else {
            gr.setValue('kyc_due_soon', false);
            gr.update();
        }
    }
})();
